const published=fs.readdirSync('static/js/document',{recursive:true}).filter(p=>p.endsWith('.js'));
const sw=fs.readFileSync('static/sw.js','utf8');
assert.equal(manifest.length,55);assert.equal(files.length,55);assert.equal(published.length,55);
for(const m of manifest){
 assert(fs.readFileSync('frontend/src/'+m.source).equals(fs.readFileSync('static/'+m.deployment)),m.source);
 assert(sw.includes('/static/'+m.deployment),m.deployment+' absent from precache');
}
